    fun forFamily(family: String): List<Variation> = routes.filter { it.family == family }.map(::variation)

    fun variation(route: StudyRoute): Variation {
        var board = BoardPosition.starting()
        val steps = route.moves.split(' ').map { token ->
            val transition = board.parseSanAndPlay(token)
            val (step, after) = PositionCoach.explainAndPlay(board, transition.move, transition.san)
            board = after
            step
        }
        val guide = OpeningGuides.forFamily(route.family)
        return Variation("ashva-study-v1:${route.family}:${route.slug}", route.title, "AUTHORED STUDY CONTINUATION",
            route.focus + " Illustrative study route, not a historical score or engine-certified best line.", steps,
            identifiesOpening = false, whiteIdea = guide.plan(true) + "\nLine focus: " + route.focus,
            blackIdea = guide.plan(false) + "\nLine focus: " + route.focus, authoredContinuation = true)
    }
}
